// Buttons, keyboard and Android touch support
for(const b of document.querySelectorAll('.part'))b.addEventListener('click',()=>{document.querySelectorAll('.part').forEach(x=>x.classList.remove('active'));b.classList.add('active');selected=b.dataset.part});
$('#startBtn').addEventListener('click',start);$('#againBtn').addEventListener('click',start);
const map={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'gas',ArrowDown:'brake',' ':'boost',a:'left',d:'right',w:'gas',s:'brake'};
addEventListener('keydown',e=>{const action=map[e.key];if(action){e.preventDefault();keys[action]=true}});addEventListener('keyup',e=>{const action=map[e.key];if(action)keys[action]=false});
for(const b of document.querySelectorAll('.ctrl')){const a=b.dataset.action;const down=e=>{e.preventDefault();keys[a]=true;b.classList.add('down');if(b.setPointerCapture&&e.pointerId!==undefined)try{b.setPointerCapture(e.pointerId)}catch{}};const up=e=>{e.preventDefault();keys[a]=false;b.classList.remove('down')};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('lostpointercapture',up)}
// Prevent browser scroll/zoom gestures during play without blocking menu scrolling.
document.addEventListener('touchmove',e=>{if(game&&!game.ended)e.preventDefault()},{passive:false});
let deferredPrompt;addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredPrompt=e;const toast=$('#toast');toast.style.opacity=1;setTimeout(()=>toast.style.opacity=0,4500)});
if('serviceWorker'in navigator&&location.protocol.startsWith('http'))addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
draw();
})();
</script>
