(()=>{
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');const $=s=>document.querySelector(s),startScreen=$('#start'),endScreen=$('#end'),hud=$('#hud'),controls=$('#controls');let W=0,H=0,dpr=1,last=0,game=null,selected='equilibrio',keys={};
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a);
function makeGame(){const tune={equilibrio:{max:108},scatto:{max:120},controllo:{max:101}}[selected];return{time:0,limit:90,dist:0,speed:0,x:0,heat:38,boost:0,boostCd:0,score:0,hits:0,top:0,tune,objects:[],spawn:0,flash:0,sector:0,rain:0,ended:false}}
function project(z){const p=1-z;return{y:H*.35+p*p*H*.67,scale:.1+p*.98}}
function drawScooter(x,y,s,lean){ctx.save();ctx.translate(x,y);ctx.rotate(lean*.22);ctx.scale(s,s);ctx.fillStyle='#10130e88';ctx.beginPath();ctx.ellipse(0,8,24,8,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#181b18';ctx.strokeStyle='#828777';ctx.lineWidth=2;for(const yy of [-20,20]){ctx.beginPath();ctx.ellipse(0,yy,7,11,0,0,Math.PI*2);ctx.fill();ctx.stroke()}ctx.fillStyle='#d5ee66';ctx.beginPath();ctx.moveTo(-14,-18);ctx.quadraticCurveTo(-17,-31,-7,-34);ctx.lineTo(9,-31);ctx.quadraticCurveTo(16,-23,14,-12);ctx.lineTo(9,17);ctx.quadraticCurveTo(0,22,-11,15);ctx.closePath();ctx.fill();ctx.fillStyle='#20281c';ctx.beginPath();ctx.roundRect(-9,-25,18,8,4);ctx.fill();ctx.fillStyle='#f5ecd0';ctx.beginPath();ctx.ellipse(0,19,9,5,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#dbf17c';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-16,-28);ctx.lineTo(-23,-32);ctx.moveTo(16,-28);ctx.lineTo(23,-32);ctx.stroke();ctx.fillStyle='#f2814c';ctx.beginPath();ctx.arc(0,-29,3,0,Math.PI*2);ctx.fill();ctx.restore()}
let messageTimer;function showMessage(text){const el=$('#message');el.textContent=text;el.style.opacity=1;clearTimeout(messageTimer);messageTimer=setTimeout(()=>el.style.opacity=0,1700)}
function draw(){ctx.clearRect(0,0,W,H);const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#829d92');sky.addColorStop(.38,'#c4c7a6');sky.addColorStop(.39,'#536e4b');sky.addColorStop(1,'#243624');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);ctx.fillStyle='#677e6e';ctx.beginPath();ctx.moveTo(0,H*.39);for(let x=0;x<=W;x+=W/6)ctx.lineTo(x,H*(.22+Math.abs(Math.sin(x*.01))*.13));ctx.lineTo(W,H*.42);ctx.closePath();ctx.fill();const prog=game?game.dist:0,curve=Math.sin(prog*.018)*.16+Math.sin(prog*.007)*.12,center=W/2+curve*W*.55,topY=H*.37,bottomY=H*1.03,topWidth=Math.min(W*.25,210),bottomWidth=Math.min(W*.91,760);ctx.fillStyle='#345039';ctx.fillRect(0,H*.38,W,H*.62);ctx.beginPath();ctx.moveTo(center-topWidth/2,topY);ctx.lineTo(center+topWidth/2,topY);ctx.lineTo(center+bottomWidth/2+12,bottomY);ctx.lineTo(center-bottomWidth/2-12,bottomY);ctx.closePath();ctx.fillStyle='#e7e0c9';ctx.fill();ctx.beginPath();ctx.moveTo(center-topWidth/2+7,topY);ctx.lineTo(center+topWidth/2-7,topY);ctx.lineTo(center+bottomWidth/2-3,bottomY);ctx.lineTo(center-bottomWidth/2+3,bottomY);ctx.closePath();ctx.fillStyle='#535650';ctx.fill();
for(let i=0;i<9;i++){let z=((i/9+(prog*.009)%1)%1),p=1-z,pt=project(z),w=topWidth+(bottomWidth-topWidth)*p,xcenter=center+curve*W*.08*p;ctx.fillStyle=i%2?'#f4edcf':'#f08359';ctx.fillRect(xcenter-w*.5-10*p,pt.y,10*p+1,19*p);ctx.fillRect(xcenter+w*.5,pt.y,10*p+1,19*p);if(i%2===0){ctx.fillStyle='#f4f0d7aa';ctx.fillRect(xcenter-2*p,pt.y,4*p,12*p)}}
for(let i=0;i<12;i++){let z=((i/12+(prog*.004)%1)%1),p=1-z,pt=project(z),x=center+(i%2?1:-1)*(topWidth*.62+(bottomWidth*.3)*p)+curve*W*.12*p,size=8+p*30;ctx.fillStyle='#1c3827';ctx.beginPath();ctx.arc(x,pt.y,size,0,Math.PI*2);ctx.fill();ctx.fillStyle='#496d45';ctx.beginPath();ctx.arc(x-size*.2,pt.y-size*.25,size*.67,0,Math.PI*2);ctx.fill()}
if(game){for(const o of game.objects){const p=project(o.z);if(o.z<0||o.z>1)continue;const roadW=topWidth+(bottomWidth-topWidth)*(1-o.z),x=center+(o.lane-.5)*roadW*.76+curve*W*.1*(1-o.z),size=7+p.scale*18;ctx.save();ctx.translate(x,p.y);if(o.type==='cone'){ctx.fillStyle='#ff8755';ctx.beginPath();ctx.moveTo(0,-size);ctx.lineTo(size*.62,size);ctx.lineTo(-size*.62,size);ctx.closePath();ctx.fill();ctx.fillStyle='#fff0d9';ctx.fillRect(-size*.45,size*.2,size*.9,size*.18)}else if(o.type==='puddle'){ctx.fillStyle='#7fa8a7aa';ctx.beginPath();ctx.ellipse(0,0,size*1.4,size*.44,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#d6eee0';ctx.stroke()}else{ctx.fillStyle='#edf0df';ctx.fillRect(-size*.8,-size*.7,size*1.6,size*1.4);ctx.fillStyle='#f08359';ctx.fillRect(-size*.8,-size*.2,size*1.6,size*.4)}ctx.restore()}
if(game.rain>.01){ctx.fillStyle=`rgba(131,171,180,${game.rain*.13})`;ctx.fillRect(0,0,W,H);if(game.rain>.3){ctx.strokeStyle='#d7e8e477';ctx.lineWidth=1;for(let i=0;i<35;i++){let x=(i*127+game.time*180)%W,y=(i*83+game.time*310)%H;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-5,y+12);ctx.stroke()}}}
const checkpoint=Math.floor(game.dist/33);if(checkpoint>game.sector){game.sector=checkpoint;showMessage(checkpoint===1?'SETTORE 2 · ASFALTO BAGNATO!':'ULTIMO SETTORE · STRINGI LE LINEE!')}drawScooter(center+game.x*bottomWidth*.37,H*.79,clamp(W/390,.72,1.08),game.x);if(game.flash>0){ctx.fillStyle=`rgba(255,132,79,${game.flash*.22})`;ctx.fillRect(0,0,W,H)}}else drawScooter(center,H*.79,clamp(W/390,.72,1.08),Math.sin(performance.now()*.001)*.1)}
function start(){game=makeGame();startScreen.classList.add('hidden');endScreen.classList.add('hidden');hud.style.display='block';controls.style.display='flex';$('#hint').style.display='block';last=performance.now();requestAnimationFrame(loop)}
function endGame(win){if(!game||game.ended)return;game.ended=true;hud.style.display='none';controls.style.display='none';$('#hint').style.display='none';endScreen.classList.remove('hidden');$('#resultEyebrow').textContent=win?'Prova completata':'Fuori tempo';$('#resultTitle').innerHTML=win?'PASSO<br><em>CONQUISTATO!</em>':'CI RIPROVIAMO?';$('#resultText').textContent=win?'Hai domato la salita senza perdere la linea. Il tuo cinquantino vola!':'La salita non aspetta: ricarica e affronta di nuovo il Passo.';$('#resultTime').textContent=`${String(Math.floor(game.time/60)).padStart(2,'0')}:${String(Math.floor(game.time%60)).padStart(2,'0')}`;$('#resultScore').textContent=game.score.toLocaleString('it-IT');$('#resultTop').textContent=`${Math.round(game.top)} km/h`;$('#resultHits').textContent=game.hits}
function update(dt){if(!game||game.ended)return;game.time+=dt;const left=keys.left,right=keys.right,gas=keys.gas||keys.ArrowUp,brake=keys.brake||keys.ArrowDown,boost=keys.boost;const steer=(right?1:0)-(left?1:0);game.x=clamp(game.x+steer*dt*(1.55+game.speed*.007),-1.22,1.22);if(Math.abs(game.x)>1){game.speed=Math.max(15,game.speed-27*dt);game.flash=Math.max(game.flash,.7)}if(gas)game.speed+=dt*(22+(game.speed<45?14:0));else game.speed-=dt*7;if(brake)game.speed-=dt*40;if(boost&&game.boostCd<=0&&game.heat<93){game.boost=1.35;game.boostCd=6.5;game.heat+=12;game.score+=120;showMessage('FRIZIONE RAPIDA! +120')}if(game.boost>0){game.boost-=dt;game.speed+=dt*31;game.heat+=dt*8}else game.heat-=dt*(gas?1.1:2.1);game.heat=clamp(game.heat,30,100);game.boostCd=Math.max(0,game.boostCd-dt);if(game.heat>88)game.speed-=dt*15;game.speed=clamp(game.speed,0,game.tune.max);game.top=Math.max(game.top,game.speed);game.dist+=dt*(game.speed/75)*1.45;game.rain=clamp((game.dist-34)/6,0,1)*clamp((70-game.dist)/5,0,1);if(game.rain>.1&&Math.random()<dt*.24)game.rain=Math.max(game.rain,.45);game.spawn-=dt;if(game.spawn<=0){game.spawn=rand(.72,1.22);const r=Math.random();game.objects.push({z:1,lane:rand(-.82,.82),type:r<.57?'cone':r<.82?'puddle':'gate'})}for(const o of game.objects){const previous=o.z;o.z-=dt*(.19+game.speed*.0023);if(previous>.13&&o.z<=.13){if(Math.abs(game.x-o.lane)<.21){game.hits++;game.speed=Math.max(12,game.speed-(o.type==='puddle'?22:17));game.score=Math.max(0,game.score-70);game.flash=.9;game.heat+=o.type==='puddle'?2:0;showMessage(o.type==='puddle'?'ATTENTO, ASFALTO BAGNATO!':'CONO SFIORATO · -70')}else game.score+=100}}game.objects=game.objects.filter(o=>o.z>-.08);game.flash=Math.max(0,game.flash-dt);game.score+=dt*(gas?Math.round(game.speed/9):0);if(game.dist>=100){game.dist=100;endGame(true)}else if(game.time>=game.limit)endGame(false);$('#speed').innerHTML=`${Math.round(game.speed)}<span> km/h</span>`;$('#distance').innerHTML=`${Math.floor(game.dist)}<span>%</span>`;$('#progress').style.width=`${game.dist}%`;const h=$('#heat');h.innerHTML=`${Math.round(game.heat)}<span>°</span>`;h.style.color=game.heat>83?'#ff8755':'#e5f0d2'}
function loop(t){if(!game||game.ended)return;const dt=Math.min(.04,(t-last)/1000||0);last=t;update(dt);draw();if(game&&!game.ended)requestAnimationFrame(loop)}
for(const b of document.querySelectorAll('.part'))b.addEventListener('click',()=>{document.querySelectorAll('.part').forEach(x=>x.classList.remove('active'));b.classList.add('active');selected=b.dataset.part});$('#startBtn').addEventListener('click',start);$('#againBtn').addEventListener('click',start);const map={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'gas',ArrowDown:'brake',' ':'boost',a:'left',d:'right',w:'gas',s:'brake'};addEventListener('keydown',e=>{const a=map[e.key];if(a){e.preventDefault();keys[a]=true}});addEventListener('keyup',e=>{const a=map[e.key];if(a)keys[a]=false});for(const b of document.querySelectorAll('.ctrl')){const a=b.dataset.action,down=e=>{e.preventDefault();keys[a]=true;b.classList.add('down');if(b.setPointerCapture&&e.pointerId!==undefined)try{b.setPointerCapture(e.pointerId)}catch{}},up=e=>{e.preventDefault();keys[a]=false;b.classList.remove('down')};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('lostpointercapture',up)}document.addEventListener('touchmove',e=>{if(game&&!game.ended)e.preventDefault()},{passive:false});if('serviceWorker'in navigator&&location.protocol.startsWith('http'))addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));draw();
})();
</script></body></html>
